import java.util.Scanner;
public class SearchMatrix {static boolean searchMatrix(int[][]m,int target){int rows=m.length,cols=m[0].length,low=0,high=rows*cols-1;while(low<=high){int mid=low+(high-low)/2,value=m[mid/cols][mid%cols];if(value==target)return true;if(value<target)low=mid+1;else high=mid-1;}return false;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Rows: ");int r=sc.nextInt();System.out.print("Columns: ");int c=sc.nextInt();if(r<=0||c<=0){System.out.println("Dimensions must be positive");sc.close();return;}int[][]m=new int[r][c];System.out.println("Enter elements in sorted matrix order row-wise:");for(int i=0;i<r;i++)for(int j=0;j<c;j++)m[i][j]=sc.nextInt();System.out.print("Target: ");int t=sc.nextInt();System.out.println(searchMatrix(m,t));sc.close();}}